export function ChunkErrorWrapper({ children }) {
  useEffect(() => {
    const handleError = (e) => {
      if (e.message?.includes('Loading chunk') || e.name === 'ChunkLoadError') {
        window.location.reload(); // Force refresh to fetch active deployment build HTML
